   101	        // eslint-disable-next-line react/jsx-props-no-spreading
   102	        <GenericTooltip {...props}>
   103	            {({isVisible, showTooltip, hideTooltip, updateTargetBounds}) =>
   104	                // Checks if valid element so we can wrap the BoundsObserver around it
   105	                // If not, we just return the primitive children
   106	                React.isValidElement(children) ? (
   107	                    <BoundsObserver
   108	                        enabled={isVisible}
   109	                        onBoundsChange={(bounds) => {
   110	                            updateTargetBounds(getBounds(bounds));
